#!/usr/bin/env python3
"""
Civ6 District Adjacency Bonus Optimizer
Scenario 3: Large city with full district build (pop 9, 1 city)
"""

import sqlite3
import json
from itertools import combinations, permutations
from collections import defaultdict

# ============================================================
# MAP PARSING
# ============================================================

MAP_PATH = '/data/maps/e2e_test_case_0.Civ6Map'

conn = sqlite3.connect(MAP_PATH)
cursor = conn.cursor()

# Map dimensions
cursor.execute("SELECT Width, Height, WrapX FROM Map")
row = cursor.fetchone()
WIDTH = row[1]
HEIGHT = row[2]
WRAP_X = bool(row[3])
print(f"Map: {WIDTH}x{HEIGHT}, WrapX={WRAP_X}")

# ============================================================
# HEX GRID UTILITIES
# ============================================================

def get_neighbors(x, y):
    """Get 6 hex neighbors: [NE, E, SE, SW, W, NW]"""
    if y % 2 == 0:
        offsets = [(0,1), (1,0), (0,-1), (-1,-1), (-1,0), (-1,1)]
    else:
        offsets = [(1,1), (1,0), (1,-1), (0,-1), (-1,0), (0,1)]

    result = []
    for dx, dy in offsets:
        nx, ny = x + dx, y + dy
        if WRAP_X:
            nx = nx % WIDTH
        if 0 <= ny < HEIGHT and 0 <= nx < WIDTH:
            result.append((nx, ny))
        else:
            result.append(None)
    return result

def offset_to_cube(x, y):
    cx = x - (y - (y & 1)) // 2
    cz = y
    cy = -cx - cz
    return cx, cy, cz

def hex_distance(x1, y1, x2, y2):
    if WRAP_X:
        best = float('inf')
        for dx in [-WIDTH, 0, WIDTH]:
            c1 = offset_to_cube(x1, y1)
            c2 = offset_to_cube(x2 + dx, y2)
            d = max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2]))
            best = min(best, d)
        return best
    else:
        c1 = offset_to_cube(x1, y1)
        c2 = offset_to_cube(x2, y2)
        return max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2]))

# ============================================================
# LOAD MAP DATA
# ============================================================

plots = {}
cursor.execute("SELECT ID, TerrainType, IsImpassable FROM Plots")
for pid, terrain, impassable in cursor.fetchall():
    x, y = pid % WIDTH, pid // WIDTH
    plots[(x, y)] = {
        'terrain': terrain,
        'impassable': bool(impassable),
        'feature': None,
        'resource': None,
        'has_river': False,
        'is_mountain': 'MOUNTAIN' in terrain,
        'is_hills': 'HILLS' in terrain,
        'is_land': terrain not in ('TERRAIN_OCEAN', 'TERRAIN_COAST'),
        'is_coast': terrain == 'TERRAIN_COAST',
        'is_water': terrain in ('TERRAIN_OCEAN', 'TERRAIN_COAST'),
    }

# Features
cursor.execute("SELECT ID, FeatureType FROM PlotFeatures")
for pid, feature in cursor.fetchall():
    x, y = pid % WIDTH, pid // WIDTH
    if (x, y) in plots:
        plots[(x, y)]['feature'] = feature

# Resources
cursor.execute("SELECT ID, ResourceType FROM PlotResources")
for pid, resource in cursor.fetchall():
    x, y = pid % WIDTH, pid // WIDTH
    if (x, y) in plots:
        plots[(x, y)]['resource'] = resource

# Rivers - build edge set
river_edges = set()
cursor.execute("SELECT * FROM PlotRivers")
for row in cursor.fetchall():
    pid = row[0]
    is_ne, is_w, is_nw = bool(row[1]), bool(row[2]), bool(row[3])
    x, y = pid % WIDTH, pid // WIDTH
    neighbors = get_neighbors(x, y)
    # neighbors: [NE=0, E=1, SE=2, SW=3, W=4, NW=5]

    if is_ne and neighbors[0]:
        river_edges.add(frozenset([(x,y), neighbors[0]]))
    if is_w and neighbors[4]:
        river_edges.add(frozenset([(x,y), neighbors[4]]))
    if is_nw and neighbors[5]:
        river_edges.add(frozenset([(x,y), neighbors[5]]))

# Mark tiles adjacent to rivers
for edge in river_edges:
    for tile in edge:
        if tile in plots:
            plots[tile]['has_river'] = True

conn.close()

# ============================================================
# IDENTIFY VALID TILES
# ============================================================

# Buildable land tiles (not mountain, not impassable, actual land)
buildable_land = []
for (x, y), p in plots.items():
    if p['is_land'] and not p['impassable'] and not p['is_mountain']:
        # Exclude natural wonders (they aren't removable features)
        feat = p['feature']
        if feat and feat in ('FEATURE_ICE',):
            continue
        buildable_land.append((x, y))

print(f"Buildable land tiles: {len(buildable_land)}")
for t in sorted(buildable_land):
    p = plots[t]
    print(f"  {t}: terrain={p['terrain']} feature={p['feature']} river={p['has_river']} mountain={p['is_mountain']}")

# Buildable coast tiles (for Harbor)
buildable_coast = []
for (x, y), p in plots.items():
    if p['is_coast'] and not p['impassable']:
        feat = p['feature']
        if feat == 'FEATURE_ICE':
            continue
        buildable_coast.append((x, y))

print(f"\nBuildable coast tiles: {len(buildable_coast)}")

# ============================================================
# DISTRICT DEFINITIONS
# ============================================================

# Population 9 → 3 regular district slots
# Plus: Aqueduct, Dam, Government Plaza (don't count against cap)
NUM_REGULAR_DISTRICTS = 3

# Districts and whether they count against the cap
REGULAR_DISTRICTS = [
    'CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE',
    'THEATER_SQUARE', 'ENTERTAINMENT_COMPLEX', 'HARBOR',
    'ENCAMPMENT', 'DIPLOMATIC_QUARTER'
]

FREE_DISTRICTS = ['AQUEDUCT', 'DAM', 'GOVERNMENT_PLAZA']

def tile_has_river_edge(x, y):
    """Check if tile has any river edge"""
    for edge in river_edges:
        if (x, y) in edge:
            return True
    return False

def is_adjacent(x1, y1, x2, y2):
    """Check if two tiles are adjacent"""
    neighbors = get_neighbors(x1, y1)
    return (x2, y2) in neighbors

# ============================================================
# ADJACENCY CALCULATION
# ============================================================

def calculate_adjacency(district_type, dx, dy, placement_map):
    """
    Calculate adjacency bonus for a district at (dx, dy).
    placement_map: dict mapping (x,y) -> district_type (including 'CITY_CENTER')
    """
    neighbors = get_neighbors(dx, dy)
    valid_neighbors = [n for n in neighbors if n is not None]

    bonus = 0

    # Count adjacent things
    adj_mountains = 0
    adj_forests = 0  # woods
    adj_jungles = 0  # rainforest
    adj_districts = 0
    adj_geothermal = 0
    adj_reefs = 0
    adj_natural_wonders = 0
    adj_city_center = 0
    adj_wonders = 0  # world wonders (none on this map)
    adj_entertainment = 0
    adj_harbor = 0
    adj_aqueduct = 0
    adj_dam = 0
    adj_government_plaza = 0
    has_river = tile_has_river_edge(dx, dy)

    for n in valid_neighbors:
        if n is None:
            continue
        nx, ny = n
        p = plots.get(n)
        if p is None:
            continue

        # Check if neighbor has a district/city placed
        if n in placement_map:
            adj_districts += 1
            placed_type = placement_map[n]
            if placed_type == 'CITY_CENTER':
                adj_city_center += 1
            elif placed_type == 'HARBOR':
                adj_harbor += 1
            elif placed_type == 'ENTERTAINMENT_COMPLEX':
                adj_entertainment += 1
            elif placed_type == 'AQUEDUCT':
                adj_aqueduct += 1
            elif placed_type == 'DAM':
                adj_dam += 1
            elif placed_type == 'GOVERNMENT_PLAZA':
                adj_government_plaza += 1
        else:
            # Natural terrain (not occupied by a district)
            if p['is_mountain']:
                adj_mountains += 1

            # Features of the tile (only count if no district placed there)
            feat = p.get('feature')
            if feat:
                if feat == 'FEATURE_FOREST':
                    adj_forests += 1
                elif feat == 'FEATURE_JUNGLE':
                    adj_jungles += 1
                elif feat == 'FEATURE_GEOTHERMAL_FISSURE':
                    adj_geothermal += 1
                elif feat == 'FEATURE_REEF':
                    adj_reefs += 1

    # Calculate based on district type
    if district_type == 'CAMPUS':
        bonus += adj_mountains  # +1 per mountain
        bonus += adj_jungles // 2  # +1 per 2 rainforest
        bonus += adj_districts // 2  # +1 per 2 districts
        bonus += adj_geothermal * 2  # +2 per geothermal fissure
        bonus += adj_reefs  # +1 per reef

    elif district_type == 'HOLY_SITE':
        bonus += adj_mountains  # +1 per mountain
        bonus += adj_forests // 2  # +1 per 2 woods
        bonus += adj_districts // 2  # +1 per 2 districts
        bonus += adj_natural_wonders * 2  # +2 per natural wonder

    elif district_type == 'COMMERCIAL_HUB':
        if has_river:
            bonus += 2  # +2 for river adjacency
        bonus += adj_harbor * 2  # +2 for adjacent harbor
        bonus += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'HARBOR':
        bonus += adj_city_center * 2  # +2 for adjacent city center
        # +1 per sea resource (none on this map apparently)
        bonus += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'INDUSTRIAL_ZONE':
        # +1 per adjacent mine/quarry (no improvements on this map)
        bonus += adj_districts // 2  # +1 per 2 districts
        bonus += adj_aqueduct * 2  # +2 per adjacent aqueduct
        bonus += adj_dam * 2  # +2 per adjacent dam

    elif district_type == 'THEATER_SQUARE':
        bonus += adj_wonders * 2  # +2 per world wonder
        bonus += adj_districts // 2  # +1 per 2 districts
        bonus += adj_entertainment * 2  # +2 per entertainment complex

    elif district_type == 'ENTERTAINMENT_COMPLEX':
        bonus += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'ENCAMPMENT':
        pass  # No adjacency bonuses

    elif district_type == 'GOVERNMENT_PLAZA':
        # +1 per adjacent district (not per 2)
        bonus += adj_districts  # Each adjacent district gives +1

    elif district_type == 'AQUEDUCT':
        pass  # No adjacency bonuses for itself

    elif district_type == 'DAM':
        pass  # No adjacency bonuses for itself

    elif district_type == 'DIPLOMATIC_QUARTER':
        bonus += adj_districts // 2  # +1 per 2 districts

    return bonus

# ============================================================
# PLACEMENT VALIDATION
# ============================================================

def can_place_district(district_type, x, y, city_center, placement_map):
    """Check if a district can be placed at (x, y)"""
    tile = (x, y)
    p = plots.get(tile)
    if p is None:
        return False

    # Already occupied
    if tile in placement_map:
        return False

    # Within 3 tiles of city center
    cx, cy = city_center
    if hex_distance(x, y, cx, cy) > 3:
        return False

    if district_type == 'HARBOR':
        # Must be on coast
        if not p['is_coast']:
            return False
        if p['impassable']:
            return False
        feat = p.get('feature')
        if feat == 'FEATURE_ICE':
            return False
        return True

    # For land districts
    if not p['is_land']:
        return False
    if p['impassable'] or p['is_mountain']:
        return False

    feat = p.get('feature')
    if feat == 'FEATURE_ICE':
        return False

    if district_type == 'ENCAMPMENT':
        # Cannot be adjacent to city center
        if hex_distance(x, y, cx, cy) == 1:
            return False

    if district_type == 'AQUEDUCT':
        # Must be adjacent to city center
        if hex_distance(x, y, cx, cy) != 1:
            return False
        # Must be adjacent to mountain or fresh water (river)
        neighbors = get_neighbors(x, y)
        has_mountain_or_water = False
        for n in neighbors:
            if n is None:
                continue
            np = plots.get(n)
            if np and np['is_mountain']:
                has_mountain_or_water = True
                break
        if not has_mountain_or_water:
            # Check if adjacent to river
            if tile_has_river_edge(x, y):
                has_mountain_or_water = True
        if not has_mountain_or_water:
            return False

    if district_type == 'DAM':
        # Must be on floodplains
        if not feat or 'FLOODPLAINS' not in feat:
            return False
        # Must be adjacent to a river
        if not tile_has_river_edge(x, y):
            return False

    return True

# ============================================================
# SOLVER
# ============================================================

def get_tiles_in_range(cx, cy, radius):
    """Get all tiles within hex distance radius of city center"""
    result = []
    # Scan a reasonable area
    for dy in range(-radius-1, radius+2):
        for dx in range(-radius-1, radius+2):
            x, y = cx + dx, cy + dy
            if WRAP_X:
                x = x % WIDTH
            if 0 <= y < HEIGHT and 0 <= x < WIDTH:
                if hex_distance(x, y, cx, cy) <= radius:
                    result.append((x, y))
    return result

def solve():
    best_total = -1
    best_solution = None

    # Try each buildable land tile as city center
    for cc in buildable_land:
        cx, cy = cc

        # Get tiles within range 3
        tiles_in_range = get_tiles_in_range(cx, cy, 3)

        # Find valid tiles for each district type
        placement_map_base = {cc: 'CITY_CENTER'}

        # Identify which free districts can be placed
        possible_free = []

        # Check for Dam placement (floodplains + river)
        dam_tiles = []
        for t in tiles_in_range:
            if can_place_district('DAM', t[0], t[1], cc, placement_map_base):
                dam_tiles.append(t)

        # Check for Aqueduct placement
        aqueduct_tiles = []
        for t in tiles_in_range:
            if can_place_district('AQUEDUCT', t[0], t[1], cc, placement_map_base):
                aqueduct_tiles.append(t)

        # Government Plaza can go anywhere valid
        gov_tiles = []
        for t in tiles_in_range:
            if can_place_district('GOVERNMENT_PLAZA', t[0], t[1], cc, placement_map_base):
                gov_tiles.append(t)

        # Regular district valid tiles
        regular_valid = {}
        for dtype in REGULAR_DISTRICTS:
            valid = []
            for t in tiles_in_range:
                if can_place_district(dtype, t[0], t[1], cc, placement_map_base):
                    valid.append(t)
            if valid:
                regular_valid[dtype] = valid

        # We need to choose 3 regular districts and optionally free districts
        # Try various combinations

        # Generate all combinations of 3 regular districts from available types
        available_regular = [d for d in REGULAR_DISTRICTS if d in regular_valid]

        for regular_combo in combinations(available_regular, min(NUM_REGULAR_DISTRICTS, len(available_regular))):
            # Also try with fewer districts if we don't have enough types
            # For each combo of regular districts, try adding free districts

            # Generate all possible free district inclusions
            free_options = []
            if dam_tiles:
                free_options.append('DAM')
            if aqueduct_tiles:
                free_options.append('AQUEDUCT')
            if gov_tiles:
                free_options.append('GOVERNMENT_PLAZA')

            # Try all subsets of free districts
            for num_free in range(len(free_options) + 1):
                for free_combo in combinations(free_options, num_free):
                    all_districts = list(regular_combo) + list(free_combo)

                    # Now try to find best placement for this set of districts
                    # Get valid tiles for each
                    district_tiles = {}
                    for d in all_districts:
                        if d in regular_valid:
                            district_tiles[d] = regular_valid[d]
                        elif d == 'DAM':
                            district_tiles[d] = dam_tiles
                        elif d == 'AQUEDUCT':
                            district_tiles[d] = aqueduct_tiles
                        elif d == 'GOVERNMENT_PLAZA':
                            district_tiles[d] = gov_tiles

                    # Try all valid placement combinations
                    result = try_placements(cc, all_districts, district_tiles, 0, {cc: 'CITY_CENTER'})
                    if result and result[0] > best_total:
                        best_total = result[0]
                        best_solution = result[1]
                        print(f"New best: total={best_total} at CC={cc}")
                        print(f"  Districts: {result[1]}")

    return best_total, best_solution

def try_placements(city_center, districts, district_tiles, idx, placement_map):
    """Recursively try placing districts and return best (total, placement_map)"""
    if idx == len(districts):
        # Calculate total adjacency
        total = 0
        bonuses = {}
        for tile, dtype in placement_map.items():
            if dtype != 'CITY_CENTER':
                b = calculate_adjacency(dtype, tile[0], tile[1], placement_map)
                bonuses[dtype] = b
                total += b
        return (total, dict(placement_map))

    dtype = districts[idx]
    valid_tiles = district_tiles[dtype]

    best = None
    for t in valid_tiles:
        if t in placement_map:
            continue
        # Revalidate (in case another district was placed that conflicts)
        if not can_place_district(dtype, t[0], t[1], city_center, placement_map):
            continue

        placement_map[t] = dtype
        result = try_placements(city_center, districts, district_tiles, idx + 1, placement_map)
        del placement_map[t]

        if result is not None:
            if best is None or result[0] > best[0]:
                best = result

    return best

print("\n=== Starting solver ===\n")
best_total, best_solution = solve()

print(f"\n=== BEST SOLUTION ===")
print(f"Total adjacency: {best_total}")
if best_solution:
    for tile, dtype in best_solution.items():
        print(f"  {dtype}: {tile}")

# Generate output
if best_solution:
    city_center = None
    placements = {}
    adjacency_bonuses = {}

    for tile, dtype in best_solution.items():
        if dtype == 'CITY_CENTER':
            city_center = list(tile)
        else:
            placements[dtype] = list(tile)
            adjacency_bonuses[dtype] = calculate_adjacency(dtype, tile[0], tile[1], best_solution)

    total = sum(adjacency_bonuses.values())

    output = {
        "city_center": city_center,
        "placements": placements,
        "adjacency_bonuses": adjacency_bonuses,
        "total_adjacency": total
    }

    print(f"\nOutput JSON:")
    print(json.dumps(output, indent=2))

    with open('/output/scenario_3.json', 'w') as f:
        json.dump(output, f, indent=2)
    print(f"\nSolution written to /output/scenario_3.json")

