        feat = p.get('feature')
        if feat == 'FEATURE_ICE':
            return False
        return True

    # For land districts
    if not p['is_land']:
        return False
    if p['impassable'] or p['is_mountain']:
        return False

    feat = p.get('feature')
    if feat == 'FEATURE_ICE':
        return False

    if district_type == 'ENCAMPMENT':
        # Cannot be adjacent to city center
        if hex_distance(x, y, cx, cy) == 1:
            return False

    if district_type == 'AQUEDUCT':
        # Must be adjacent to city center
        if hex_distance(x, y, cx, cy) != 1:
            return False
        # Must be adjacent to mountain or fresh water (river)
        neighbors = get_neighbors(x, y)
        has_mountain_or_water = False
        for n in neighbors:
            if n is None:
                continue
            np = plots.get(n)
            if np and np['is_mountain']:
                has_mountain_or_water = True
                break
        if not has_mountain_or_water:
            # Check if adjacent to river
            if tile_has_river_edge(x, y):
                has_mountain_or_water = True
        if not has_mountain_or_water:
            return False

    if district_type == 'DAM':
        # Must be on floodplains
        if not feat or 'FLOODPLAINS' not in feat:
            return False
        # Must be adjacent to a river
        if not tile_has_river_edge(x, y):
            return False

    return True

