def get_tiles_in_range(cx, cy, radius):
    """Get all tiles within hex distance radius of city center"""
    result = []
    # Scan a reasonable area
    for dy in range(-radius-1, radius+2):
        for dx in range(-radius-1, radius+2):
            x, y = cx + dx, cy + dy
            if WRAP_X:
                x = x % WIDTH
            if 0 <= y < HEIGHT and 0 <= x < WIDTH:
                if hex_distance(x, y, cx, cy) <= radius:
                    result.append((x, y))
    return result

def solve():
    best_total = -1
    best_solution = None

    # Try each buildable land tile as city center
    for cc in buildable_land:
        cx, cy = cc

        # Get tiles within range 3
        tiles_in_range = get_tiles_in_range(cx, cy, 3)

        # Find valid tiles for each district type
        placement_map_base = {cc: 'CITY_CENTER'}

        # Identify which free districts can be placed
        possible_free = []

        # Check for Dam placement (floodplains + river)
        dam_tiles = []
        for t in tiles_in_range:
            if can_place_district('DAM', t[0], t[1], cc, placement_map_base):
                dam_tiles.append(t)

        # Check for Aqueduct placement
        aqueduct_tiles = []
        for t in tiles_in_range:
            if can_place_district('AQUEDUCT', t[0], t[1], cc, placement_map_base):
                aqueduct_tiles.append(t)

        # Government Plaza can go anywhere valid
        gov_tiles = []
        for t in tiles_in_range:
            if can_place_district('GOVERNMENT_PLAZA', t[0], t[1], cc, placement_map_base):
                gov_tiles.append(t)

        # Regular district valid tiles
        regular_valid = {}
        for dtype in REGULAR_DISTRICTS:
            valid = []
            for t in tiles_in_range:
                if can_place_district(dtype, t[0], t[1], cc, placement_map_base):
                    valid.append(t)
            if valid:
                regular_valid[dtype] = valid

        # We need to choose 3 regular districts and optionally free districts
        # Try various combinations

        # Generate all combinations of 3 regular districts from available types
        available_regular = [d for d in REGULAR_DISTRICTS if d in regular_valid]

        for regular_combo in combinations(available_regular, min(NUM_REGULAR_DISTRICTS, len(available_regular))):
            # Also try with fewer districts if we don't have enough types
            # For each combo of regular districts, try adding free districts

            # Generate all possible free district inclusions
            free_options = []
            if dam_tiles:
                free_options.append('DAM')
            if aqueduct_tiles:
                free_options.append('AQUEDUCT')
            if gov_tiles:
                free_options.append('GOVERNMENT_PLAZA')

            # Try all subsets of free districts
            for num_free in range(len(free_options) + 1):
                for free_combo in combinations(free_options, num_free):
                    all_districts = list(regular_combo) + list(free_combo)

                    # Now try to find best placement for this set of districts
                    # Get valid tiles for each
                    district_tiles = {}
                    for d in all_districts:
                        if d in regular_valid:
                            district_tiles[d] = regular_valid[d]
                        elif d == 'DAM':
                            district_tiles[d] = dam_tiles
                        elif d == 'AQUEDUCT':
                            district_tiles[d] = aqueduct_tiles
                        elif d == 'GOVERNMENT_PLAZA':
                            district_tiles[d] = gov_tiles

                    # Try all valid placement combinations
                    result = try_placements(cc, all_districts, district_tiles, 0, {cc: 'CITY_CENTER'})
                    if result and result[0] > best_total:
                        best_total = result[0]
                        best_solution = result[1]
                        print(f"New best: total={best_total} at CC={cc}")
                        print(f"  Districts: {result[1]}")

    return best_total, best_solution

def try_placements(city_center, districts, district_tiles, idx, placement_map):
    """Recursively try placing districts and return best (total, placement_map)"""
    if idx == len(districts):
        # Calculate total adjacency
        total = 0
        bonuses = {}
        for tile, dtype in placement_map.items():
            if dtype != 'CITY_CENTER':
                b = calculate_adjacency(dtype, tile[0], tile[1], placement_map)
                bonuses[dtype] = b
                total += b
        return (total, dict(placement_map))

    dtype = districts[idx]
    valid_tiles = district_tiles[dtype]

    best = None
    for t in valid_tiles:
        if t in placement_map:
            continue
        # Revalidate (in case another district was placed that conflicts)
        if not can_place_district(dtype, t[0], t[1], city_center, placement_map):
            continue

        placement_map[t] = dtype
        result = try_placements(city_center, districts, district_tiles, idx + 1, placement_map)
        del placement_map[t]

        if result is not None:
            if best is None or result[0] > best[0]:
                best = result

    return best

